value.value:
The ingestion process has been completed for all tables and below is the status:
@{replace(string(pipeline().parameters.table_status),'"','')}

Pipeline Run id = @{pipeline().RunId}

query.value:
select * from @{activity('Read Table Details').output.firstRow.source_schema_name}.@{activity('Read Table Details').output.firstRow.source_table_name}
@{if(equals(activity('Read Table Details').output.firstRow.load_type,'FULL'),'',
concat('where ',activity('Read Table Details').output.firstRow.watermark_column,' > ','''',activity('Read Watermark').output.firstRow.watermark_value,'''')
)}

text.value:
update ctrl.audit_log
set status='FAILED',end_time=SYSUTCDATETIME()
WHERE table_id=@{item().table_id}
and adf_run_id=@{pipeline().parameters.adf_run_id}
